import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf'}
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def verify_request_signature(req):
    """Verify HMAC signature from upstream service"""
    sig = req.headers.get('X-Request-Signature', '')
    body = req.get_data()
    expected = hmac.new(SECRET_KEY.encode(), body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    # Get output format preference
    output_format = request.form.get('format', 'pdf')

    # Create temp directory for this conversion
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)

    filename = secure_filename(file.filename)
    input_path = os.path.join(work_dir, filename)
    file.save(input_path)

    # Build LibreOffice conversion command
    # The --infilter option allows specifying import filter parameters
    infilter = request.form.get('infilter', '')

    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {work_dir}'
    if infilter:
        cmd += f' --infilter="{infilter}"'
    cmd += f' {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=work_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        # Find the output file
        base_name = os.path.splitext(filename)[0]
        output_path = os.path.join(work_dir, f'{base_name}.{output_format}')

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(
            output_path,
            as_attachment=True,
            download_name=f'{base_name}.{output_format}'
        )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

